{"content":"import json
import pandas as pd

def normalize_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, pd.Timestamp):
        return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    if not s or s.lower() == "nan" or s.lower() == "none":
        return None
    try:
        return pd.to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        return s

def normalize_status(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    # numpy bool
    if type(v).__name__ == "bool_":
        return "active" if bool(v) else "inactive"
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if v == 1:
            return "active"
        if v == 0:
            return "inactive"
        return str(v)
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", ""):
        return None
    low = s.lower()
    if low in ("true", "t", "yes", "1", "active"):
        return "active"
    if low in ("false", "f", "no", "0", "inactive"):
        return "inactive"
    return s

def sstr(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none"):
        return None
    return s

# --- Read source_a ---
with open("/data/source_a/users.json") as f:
    data_a = json.load(f)
recs_a = []
for r in data_a:
    recs_a.append({
        "user_id": int(r["id"]) if r.get("id") is not None else None,
        "name": sstr(r.get("full_name")),
        "email": sstr(r.get("email")),
        "created_date": normalize_date(r.get("registration_date")),
        "status": normalize_status(r.get("status")),
    })

# --- Read source_b ---
df_b = pd.read_csv("/data/source_b/users.csv", dtype=str, keep_default_na=False)
recs_b = []
for _, r in df_b.iterrows():
    def g(k):
        v = r.get(k, "")
        if v == "":
            return None
        return v
    uid_raw = g("user_id")
    recs_b.append({
        "user_id": int(float(uid_raw)) if uid_raw is not None else None,
        "name": sstr(g("name")),
        "email": sstr(g("email_address")),
        "created_date": normalize_date(g("created_at")),
        "status": normalize_status(g("is_active")),
    })

# --- Read source_c ---
df_c = pd.read_parquet("/data/source_c/users.parquet")
recs_c = []
for _, r in df_c.iterrows():
    def gc(k):
        if k not in r:
            return None
        v = r[k]
        if pd.isna(v):
            return None
        return v
    uid_raw = gc("userId")
    recs_c.append({
        "user_id": int(uid_raw),
        "name": sstr(gc("userName")),
        "email": sstr(gc("email")),
        "created_date": normalize_date(gc("joined")),
        "status": normalize_status(gc("active")),
    })

sources = {"source_a": recs_a, "source_b": recs_b, "source_c": recs_c}
priority = ["source_a", "source_b", "source_c"]
fields = ["name", "email", "created_date", "status"]

# per-user per-source records
by_user = {}
for src in priority:
    for rec in sources[src]:
        uid = rec["user_id"]
        by_user.setdefault(uid, {})[src] = rec

merged = []
conflicts = []
for uid in sorted(by_user):
    per_src = by_user[uid]
    row = {"user_id": int(uid)}
    for f in fields:
        vals = {}
        for src in priority:
            if src in per_src and per_src[src].get(f) is not None:
                vals[src] = per_src[src][f]
        selected = None
        for src in priority:
            if src in vals:
                selected = vals[src]
                break
        row[f] = selected
        # conflict if >=2 distinct values among present sources
        if len(set(vals.values())) > 1:
            conflicts.append({
                "user_id": int(uid),
                "field": f,
                "values": vals,
                "selected": selected,
            })
    merged.append(row)

conflicts.sort(key=lambda x: (x["user_id"], x["field"]))

df_out = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
df_out["user_id"] = df_out["user_id"].astype("int64")
df_out = df_out.sort_values("user_id").reset_index(drop=True)
df_out.to_parquet("/app/merged_users.parquet", index=False)

with open("/app/conflicts.json", "w") as f:
    json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, f, indent=2)

print(df_out.to_string())
print(df_out.dtypes)
print(json.dumps({"total_conflicts": len(conflicts), "conflicts": conflicts}, indent=2))
","path":"/app/merge_users.py"}

